// src/facets/online.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) holds online: bool, x: f32 and tags: u32; genex.toml has [net] enabled = true.
use super::World;
use genex::net::{NetConfig, NetEvent, NetStatus};
use genex::prelude::*;

/// The connected players a round needs; below it the round waits.
const MIN_PLAYERS: usize = 2;
/// A demo's step: three ticks.
const STEP_MS: u32 = 50;

/// A player's `x`, from its smoothed `state()` (drawing) or its `state_raw()` (rules).
fn x_of(state: &Value) -> Option<f32> {
    state.get("x").and_then(Value::as_f64).map(|x| x as f32)
}

pub fn wire(game: &mut Game<World>) {
    game.net(NetConfig::new().publish_hz(15).decimals(2).interp_delay_ticks(6));
    game.on_update(|sim, ctx| {
        // The commitment point: Enter on the menu is "Play online"; nothing connects on boot.
        if !sim.world.online && ctx.keys.pressed(Key::Enter) {
            sim.world.online = true;
        }
        if !sim.world.online {
            return; // the local mode never touches sim.net
        }
        if ctx.keys.pressed(Key::Escape) {
            sim.world.online = false;
            sim.net.leave(); // on purpose: no auto-reconnect
            return;
        }
        if sim.net.status() == NetStatus::Offline {
            sim.net.connect();
        }
        // Yourself: moved on the input tick and published (coalesced); never wait for the echo.
        if ctx.keys.down(Key::KeyD) {
            sim.world.x += 0.1;
        }
        sim.net.set_me(json!({ "x": sim.world.x })).ok();
        for event in sim.net.events() {
            if matches!(event, NetEvent::Closed { .. }) {
                sim.world.online = false; // replaced or closed: show it, never rejoin by itself
            }
        }
        // A rule reads state_raw(); only the host keeps the score, in a shared key.
        let me = sim.world.x;
        let touching = sim.net.remotes().any(|p| x_of(p.state_raw()).is_some_and(|x| (x - me).abs() < 1.0));
        if touching && sim.net.is_host() && sim.net.connected() >= MIN_PLAYERS {
            sim.world.tags += 1;
            sim.net.set_shared("tags", json!(sim.world.tags)).ok();
        }
    });
    game.on_draw(|sim, frame, _| {
        frame.tag("me").sphere(vec3(sim.world.x, 0.5, 0.0), 0.5, Color::WHITE); // local, never the echo
        for remote in sim.net.remotes() {
            let x = x_of(remote.state()).unwrap_or(0.0); // smoothed: drawing only
            frame.tag("remote").sphere(vec3(x, 0.5, 2.0), 0.5, Color::BLUE);
        }
    });
    game.probe("players", |sim| json!({ "connected": sim.net.connected(), "tags": sim.world.tags }));
    // Studio's loopback room: Play online seats you as host, then a scripted player joins.
    game.demo("two_players", |driver| {
        driver.inject(Input::key_tap(Key::Enter));
        driver.advance_ms(STEP_MS);
        driver.net().join("ana");
        driver.advance_ms(STEP_MS * 4);
        json!({ "connected": driver.sim().net.connected(), "tags": driver.sim().world.tags })
    });
}
